from functools import wraps
from neo4j import TransactionError

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        @wraps(func)
        def wrapper(tx, *args, **kwargs):
            if metadata is not None:
                tx.on_rollback(lambda _, exception_=None: tx.log.info(f"Transaction rolled back with metadata: {metadata}"))
                tx.on_commit(lambda _, metadata_=metadata: tx.log.info(f"Transaction committed with metadata: {metadata_}"))
                tx.run("CALL dbms.setTXMetaData($metadata)", metadata=metadata)
            if timeout is not None:
                tx.run("SET tx.timeout = $timeout", timeout=timeout)
            try:
                return func(tx, *args, **kwargs)
            except TransactionError as e:
                tx.log.error(f"Transaction failed: {e}")
                raise
        return wrapper
    return decorator
