import math

def round_half_to_even(n):
    if isinstance(n, int):
        return n
    elif isinstance(n, float):
        if n.is_integer():
            return int(n)
        else:
            n_str = str(n)
            decimal_part = int(n_str.split('.')[1])
            if decimal_part < 5:
                return math.floor(n)
            elif decimal_part > 5:
                return math.ceil(n)
            else:
                if int(n_str.split('.')[0]) % 2 == 0:
                    return int(n_str.split('.')[0])
                else:
                    return int(n_str.split('.')[0]) + 1
        # return round(n, 0)  # simpler, but not the same as the problem's rounding rules
    else:
        raise TypeError("Input must be an integer or a float")
