def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    import os
    import sys

    cmd_list = list(cmd)
    if os.name == 'nt':
        if len(cmd_list) > 0 and cmd_list[0].startswith('#!'):
            script_path = cmd_list[0].split()[-1]
            if not os.path.exists(script_path):
                script_path = os.path.join(os.path.dirname(sys.argv[0]), script_path)
            cmd_list[0] = script_path

    return tuple(cmd_list)
