def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize is None:
        maxsize = 0
    elif not isinstance(maxsize, int) or maxsize < 0:
        raise TypeError('maxsize must be None or a nonnegative integer')

    if not isinstance(ttl, (int, float)) or ttl < 0:
        raise TypeError('ttl must be a nonnegative number')

    def decorator(func):
        cache = {}
        cache_info = {
            'hits': 0,
            'misses': 0,
            'maxsize': maxsize,
            'currsize': 0
        }

        def wrapper(*args, **kwargs):
            key = args if not typed else (func, args, tuple(kwargs.items()))
            try:
                record = cache[key]
            except KeyError:
                cache_info['misses'] += 1
                result = func(*args, **kwargs)
                if maxsize:
                    if cache_info['currsize'] >= maxsize:
                        oldest_key = min(cache, key=lambda k: cache[k][1])
                        del cache[oldest_key]
                        cache_info['currsize'] -= 1
                    cache[key] = (result, timer() + ttl)
                    cache_info['currsize'] += 1
                return result
            else:
                if record[1] > timer():
                    cache_info['hits'] += 1
                    return record[0]
                else:
                    cache_info['misses'] += 1
                    result = func(*args, **kwargs)
                    del cache[key]
                    cache_info['currsize'] -= 1
                    if maxsize:
                        if cache_info['currsize'] >= maxsize:
                            oldest_key = min(cache, key=lambda k: cache[k][1])
                            del cache[oldest_key]
                            cache_info['currsize'] -= 1
                        cache[key] = (result, timer() + ttl)
                        cache_info['currsize'] += 1
                    return result

        def cache_clear():
            nonlocal cache
            cache = {}
            cache_info['hits'] = 0
            cache_info['misses'] = 0
            cache_info['currsize'] = 0

        def cache_info():
            return {
                'hits': cache_info['hits'],
                'misses': cache_info['misses'],
                'maxsize': maxsize,
                'currsize': cache_info['currsize']
            }

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info

        return wrapper

    return decorator

