def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    class TTLCache:
        def __init__(self, maxsize, ttl, timer, typed):
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed
            self.cache = {}
            self.access Order = []

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = (func, args, frozenset(kwargs.items())) if self.typed else (func, args, tuple(kwargs.items()))
                now = self.timer()
                if key in self.cache:
                    result, last_accessed = self.cache[key]
                    if now <= last_accessed + self.ttl:
                        self.access_Order.remove(key)
                        self.access_Order.append(key)
                        return result
                    else:
                        del self.cache[key]

                if len(self.cache) >= self.maxsize:
                    oldest_key = self.access_Order.pop(0)
                    del self.cache[oldest_key]

                result = func(*args, **kwargs)
                self.cache[key] = (result, now)
                self.access_Order.append(key)
                return result

            return wrapper

    return TTLCache(maxsize, ttl, timer, typed)
