def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        keyargs = {}

        def wrapper(*args, **kwargs):
            # Generate a key for the cache dictionary using the function's args and kwargs
            if typed:
                key = (func, args, tuple(kwargs.items()))
            else:
                key = (func, tuple(args), tuple(sorted(kwargs.items())))

            if key not in cache:
                if len(cache) >= maxsize:
                    # Remove the least recently used item from the cache
                    lru_key = min(keyargs, key=keyargs.get)
                    del cache[lru_key]
                    del keyargs[lru_key]
                result = func(*args, **kwargs)
                cache[key] = result
                keyargs[key] = len(keyargs)
            else:
                # Update the last recently used time
                keyargs[key] = len(keyargs)

            return cache[key]

        return wrapper

    return decorator
