def lfu_cache(maxsize=128, typed=False):
    from functools import wraps
    from collections import OrderedDict, Counter

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = OrderedDict()
            self.freq = Counter()
            self.lfu = float('inf')

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (func, args, tuple(kwargs.items())) if self.typed else (func, tuple(args), tuple(kwargs.items()))
                freq_key = (func, args, tuple(kwargs.items())) if self.typed else (func, tuple(args), tuple(kwargs.items()))

                if key in self.cache:
                    self.freq[freq_key] += 1
                    self.cache.move_to_end(key, last=True)
                    self.update_lfu()
                    return self.cache[key]

                if len(self.cache) >= self.maxsize:
                    for k in sorted(self.cache):
                        if k in self.freq and self.freq[k] == self.lfu:
                            self.cache.pop(k)
                            self.freq.pop(k)
                            self.update_lfu()
                            break

                result = func(*args, **kwargs)
                self.cache[key] = result
                self.freq[freq_key] = 1
                self.update_lfu()
