from functools import wraps
from collections import defaultdict, OrderedDict

def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        def keyfunc(args, kwargs):
            if typed:
                return args, tuple(kwargs.items())
            return tuple(args), tuple(kwargs.items())

        cache = {}
        frequency = defaultdict(OrderedDict)
        size = 0

        @wraps(func)
        def wrapper(*args, **kwargs):
            k = keyfunc(args, kwargs)
            if k in cache:
                frequency[cache[k]['freq']][k].popitem(last=False)
                freq = cache[k]['freq']
                if not frequency[freq]:
                    del frequency[freq]
                cache[k]['freq'] += 1
                frequency[cache[k]['freq']][k] = args, kwargs
                return cache[k]['value']
            elif size < maxsize:
                cache[k] = {'freq': 1, 'value': func(*args, **kwargs)}
                frequency[1][k] = args, kwargs
                size += 1
            else:
                lfu_key = None
                lfu_freq = float('inf')
                for freq, d in frequency.items():
                    if freq < lfu_freq or (freq == lfu_freq and len(d) == 1):
                        lfu_key, lfu_args, lfu_kwargs = d.popitem(last=False)
                        lfu_freq = freq
                del cache[lfu_key]
                size -= 1
                cache[k] = {'freq': 1, 'value': func(*args, **kwargs)}
                frequency[1][k] = args, kwargs
            return cache[k]['value']

        return wrapper

    return decorator
