def extostr(cls, e, max_level=30, max_path_level=5):
    def format_stack_trace(stack, level):
        if level == 0:
            return ""
        return "\n".join(f"  {frame.filename}:{frame.lineno}" for frame in stack[-level:] if frame)

    def format_exception(exc, level):
        if level == 0:
            return str(exc)
        return f"{exc.__class__.__name__}: {exc}\n{format_stack_trace(exc.__traceback__, level)}"

    if not isinstance(e, Exception):
        raise ValueError("e must be an instance of Exception")

    return format_exception(e, max_level)
