        for i, ordering in enumerate(orderings):
            if not result or not set(ordering[:1]).issubset(set(result)):
                continue
            index = result.index(ordering[0])
            result[index:index+len(ordering)] = ordering
            changed = True
            if len(ordering) > 1:
                orderings.append(ordering[1:])
                orderings.pop(i)
                break
