def _legacy_mergeOrderings(orderings):
    # Create a dictionary to store the indices of each element
    index_map = {}
    # Create a list to store the final merged ordering
    merged_ordering = []

    # Iterate over each ordering list
    for ordering in orderings:
        for i, item in enumerate(ordering):
            # If the item is already in the map, update its index in the merged ordering
            if item in index_map:
                index_map[item] = max(index_map[item], i)
            else:
                # Otherwise, add the item to the map and the merged ordering
                index_map[item] = i
                merged_ordering.append(item)

    # Sort the merged ordering based on the indices in the map
    merged_ordering.sort(key=lambda x: index_map[x])

    return merged_ordering
