def minimalBases(classes):
    def is_transitive(subset):
        return all(all(is_inherited(subset, base, cls) for base in subset) for cls in subset)

    def is_inherited(subset, base, cls):
        return base in cls.__bases__ and all(not is_inherited(subset, b, base) for b in subset if b != base)

    for i in range(len(classes), 0, -1):
        for subset in itertools.combinations(classes, i):
            if is_transitive(subset):
                return subset
    return ()
