def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal_set = []
    for c in classes:
        minimal = True
        for m in minimal_set:
            if issubclass(c, m):
                minimal = False
                break
            if issubclass(m, c):
                minimal_set.remove(m)
                minimal = True
                break
        if minimal:
            minimal_set.append(c)
    return minimal_set
