    if "value" not in context:
        context["value"] = {}
    for field in ["E", "t"]:
        if field in self.properties:
            context["value"][field] = self.properties[field]
    # Handle subcontexts
    for subcontext_field in ["x", "y", "z"]:
        if subcontext_field in self.properties:
            index = self.properties[subcontext_field]
            if subcontext_field not in context["value"]:
                context["value"][subcontext_field] = {"index": index}

