def difference(d1, d2, level=-1):
    if level == 0:
        return {}
    result = {}
    if isinstance(d1, dict):
        if not isinstance(d2, dict):
            return d1
        for key in d1:
            if key not in d2:
                result[key] = d1[key]
            else:
                diff = difference(d1[key], d2[key], level - 1)
                if diff:
                    result[key] = diff
    else:
        if d1 != d2:
            result = d1
    return result
