import re
from typing import Dict, List

class ValidationError(Exception):
    def __init__(self, messages: List[Dict[str, str]]):
        super().__init__()
        self.messages = messages

def _validate_labels(labels: Dict[str, str]) -> None:
    key_regex = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')
    value_regex = re.compile(r'^\S+$')

    errors = []
    for key, value in labels.items():
        if isinstance(value, list):
            for idx, v in enumerate(value):
                if not isinstance(v, str):
                    errors.append({"['%s'][%d]" % (key, idx): 'expected string or bytes-like object'})
        elif not isinstance(value, str):
            errors.append({"%s" % key: 'expected string or bytes-like object'})
        if isinstance(key, str):
            if not key_regex.match(key):
                errors.append({"%s" % key: "Label key '%s' does not match the regex [...]" % key})
        if isinstance(value, str):
            if not value_regex.match(value):
                errors.append({"%s" % key: "Label value '%s' does not match the regex [...]" % value})

    if errors:
        raise ValidationError(errors)
