) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if isinstance(sql, bytes):
        sql = sql.decode('utf-8')

    out_params: List[Dict[Union[str, int], Any]] = []
    out_style_params: List[Dict[Union[str, int], Any]] = []
    ordinal_index = 0

    for params in many_params:
        if isinstance(params, Mapping):
            if isinstance(sql, str):
                out_sql = self.format_with_placeholders(sql, self.SQLParams.in_style)
            elif isinstance(sql, bytes):
                out_sql = sql.decode('utf-8')
                out_sql = self.format_with_placeholders(out_sql, self.SQLParams.in_style)
                out_sql = out_sql.encode('utf-8')
        elif isinstance(params, Sequence):
            if self.SQLParams.in_style == 'named':
                out_params.append({f'param{i}': value for i, value in enumerate(params)})
                if isinstance(sql, str):
                    out_sql = sql.format(**{f'param{i}': params[i] for i in range(len(params))})
                elif isinstance(sql, bytes):
                    out_sql = sql.decode('utf-8')
                    out_sql = out_sql.format(**{f'param{i}': params[i] for i in range(len(params))})
                    out_sql = out_sql.encode('utf-8')
            elif self.SQLParams.in_style == 'ordinal':
                out_sql = self.format_with_placeholders(sql, self.SQLParams.in_style)
                out_params.append({f'param{i}': params[i] for i, value in enumerate(params)})
        else:
            raise ValueError("Params must be a mapping or a sequence")

        out_style_params.append({f'out_param{i}': value for i, value in enumerate(out_params)})
        ordinal_index += 1

    return out_sql, out_style_params
