from typing import AnyStr, Union, Iterable, Dict, Sequence, Tuple

def formatmany(
		self,
		sql: AnyStr,
		many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
	) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
		if isinstance(many_params, Iterable):
			converted_params = []
			for params in many_params:
				if isinstance(params, Mapping):
					converted_params.append({k: v for k, v in params.items()})
				elif isinstance(params, Sequence):
					converted_params.append(list(params))
			return sql, converted_params
		else:
			return sql, []
