def validate_fixity(self, fixity, manifest_files):
    # Check if the required keys are present in the fixity block
    required_keys = {'algorithm', 'checksum'}
    if not required_keys.issubset(fixity):
        return False

    # Check if all files referenced in fixity are in the manifest
    referenced_files = fixity.get('referenced_files', [])
    for file in referenced_files:
        if file not in manifest_files:
            return False

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Check if fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")

    # Check if 'files' key exists in fixity block
    if 'files' not in fixity:
        raise KeyError("Fixity block must contain 'files' key.")

    # Check if 'files' is a list
    if not isinstance(fixity['files'], list):
        raise ValueError("'files' key must be a list.")

    # Check if all files in fixity block are in manifest_files
    for file in fixity['files']:
        if file not in manifest_files:
            raise ValueError(f"File '{file}' in fixity block is not in manifest files.")

    return True

