def group_files_by_xml_filename(xml_filename: str, files: List[str]) -> Dict[str, Package]:
    grouped_files = {}
    for file in files:
        if file.endswith(xml_filename):
            basename = file[:file.index(xml_filename)]
            if basename not in grouped_files:
                grouped_files[basename] = Package(basename, [file])
            else:
                grouped_files[basename].files.append(file)
    return grouped_files
