def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if expr.startswith '&' and expr.split('&')[1].startswith('('):
            parts = expr.split('&')
            if parts[1][1:].startswith('A'):
                result.append(parts[0])
            elif parts[1][1:].startswith('~A'):
                result.append(parts[0] + parts[1][1:4])
        elif expr.startswith '|' and expr.split('|')[1].startswith('('):
            parts = expr.split('|')
            if parts[1][1:].startswith('A'):
                result.append(parts[0])
            elif parts[1][1:].startswith('~A'):
                result.append(parts[0] + parts[1][1:4])
        else:
            result.append(expr)
    return result
```

