def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    version_parts = list(map(int, version.split('.')))
    for i in reversed(range(len(version_parts))):
        if version_parts[i] < 9:
            version_parts[i] += 1
            version_parts[i+1:] = [0] * (len(version_parts) - i - 1)
            return '.'.join(map(str, version_parts))
    version_parts.append(1)
    return '.'.join(map(str, version_parts))

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = {}
    version_inventories = {}
    content_digests = {}

    # Load the root inventory
    root_inventory_file = os.path.join(version_dirs[0], 'inventory.txt')
    with open(root_inventory_file, 'r') as file:
        for line in file:
            version, digest = line.strip().split(':')
            root_inventory[version] = digest

    # Validate each version inventory
    for version_dir in version_dirs[1:]:
        version_inventory_file = os.path.join(version_dir, 'inventory.txt')
        with open(version_inventory_file, 'r') as file:
            version = os.path.basename(version_dir)
            for line in file:
                sub_version, sub_digest = line.strip().split(':')
                if sub_version not in version_inventory:
                    version_inventory[sub_version] = []
                version_inventory[sub_version].append(sub_digest)

                if sub_version not in root_inventory:
                    print(f"Version {sub_version} not found in root inventory")
                elif root_inventory[sub_version] != sub_digest:
                    print(f"Content digest for version {sub_version} differs from root inventory")
                    if sub-version not in content_digests:
                        content_digests[sub_version] = []
                    content_digests[sub_version].append(sub_digest)

    return version_inventory, content_digests

