def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = []

    for subparser_name, parser in subparsers.items():
        subparser_args = unparsed_arguments.copy()
        while subparser_args:
            try:
                parsed_args, _ = parser.parse_known_args(subparser_args)
                parsed_arguments[subparser_name] = parsed_args
                subparser_args = [arg for arg in subparser_args if arg not in dir(parsed_args)]
            except SystemExit:
                break
        remaining_arguments += subparser_args

    return (parsed_arguments, remaining_arguments)
