def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_namespaces = {}
    remaining_arguments = unparsed_arguments[:]

    for subparser_name, argparse_parser in subparsers.items():
        # Create a parser that will inherit common arguments from the main parser
        subparser = argparse.ArgumentParser(parents=[argparse_parser])

        # Check if the subparser can parse the remaining arguments
        namespace, unknown = subparser.parse_known_args(remaining_arguments)

        # If the subparser parsed any arguments, save the parsed namespace
        if unknown != remaining_arguments:
            parsed_namespaces[subparser_name] = namespace
            remaining_arguments = unknown

    return parsed_namespaces, remaining_arguments

