    if not alphabet:
        raise ValueError("Alphabet list cannot be empty")

    if number == 0:
        return alphabet[0] if padding is None or padding == 0 else alphabet[0] * padding

    digits = []
    negative = number < 0
    if negative:
        number = -number

    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

