import logging
import json
import os

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configurations = {}
    errors = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                if overrides is not None:
                    config.update(overrides)
                if resolve_env:
                    config = resolve_environment_variables(config)
                configurations[filename] = config
        except Exception as e:
            error = logging.LogRecord('load_configurations', logging.ERROR, filename, 0, str(e), (), None)
            errors.append(error)

    return configurations, errors

def resolve_environment_variables(config):
    import re
    regex = re.compile(r'\$\{([^}]+)\}')
    for key, value in config.items():
        while type(value) in [list, str]:
            if isinstance(value, list):
                value = [regex.sub(lambda m: os.getenv(m.group(1), m.group(0)), v) for v in value]
            elif isinstance(value, str):
                value = regex.sub(lambda m: os.getenv(m.group(1), m.group(0)), value)
            if value != config[key]:
                config[key] = value
    return config
