import logging
import json

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    configurations = {}
    parse_errors = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as file:
                config_data = json.load(file)
                if resolve_env:
                    config_data = resolve_environment_variables(config_data)
                if overrides:
                    config_data = override_configurations(config_data, overrides)
                configurations[config_filename] = config_data
        except json.JSONDecodeError as e:
            parse_errors.append(create_log_record(config_filename, str(e), logging.ERROR))
        except FileNotFoundError as e:
            parse_errors.append(create_log_record(config_filename, str(e), logging.ERROR))
        except Exception as e:
            parse_errors.append(create_log_record(config_filename, str(e), logging.ERROR))

    return configurations, parse_errors

def resolve_environment_variables(config_data):
    import os
    return json.loads(json.dumps(config_data).replace('${', '{').replace('}', '}'), object_hook=os.path.expandvars)

def override_configurations(config_data, overrides):
    for key, value in overrides.items():
        keys = key.split('.')
        current = config_data
        for k in keys[:-1]:
            current = current.setdefault(k, {})
        current[keys[-1]] = value
    return config_data

def create_log_record(config_filename, message, level):
    logger = logging.getLogger(__name__)
    return logger.makeRecord(__name__, level, config_filename, None, message, None, None)
