import logging

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''

    import yaml
    from jinja2 import Environment, FileSystemLoader

    config_dict = {}
    log_records = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as file:
                config_content = file.read()

                if resolve_env:
                    env = Environment(loader=FileSystemLoader('/'))  # Assuming environment variables are global
                    config_content = env.from_string(config_content).render()

                config_data = yaml.safe_load(config_content)
                config_dict[config_filename] = config_data

        except Exception as e:
            error_record = logging.LogRecord(name='config_loader', level=logging.ERROR, filename=config_filename, lineno=0, msg=str(e), args=())
            log_records.append(error_record)

    if overrides:
        for key, value in overrides.items():
            if key in config_dict:
                config_dict[key].update(value)

    return config_dict, log_records
