import logging
from typing import List, Dict, Any

def load_configurations(config_filenames: List[str], overrides: Dict[str, Any] = None, resolve_env: bool = True) -> (Dict[str, Any], List[logging.LogRecord]):
    config_dict = {}
    log_records = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as file:
                config = eval(file.read(), {}, {})  # Assuming config files are small and safe to eval
                config_dict[config_filename] = config

                if overrides:
                    config.update(overrides)

                if resolve_env:
                    import os
                    for key, value in config.items():
                        if isinstance(value, str) and value.startswith('${'):
                            env_var = value[2:-1]
                            ENV_FILE_OR_VALUE = os.getenv(env_var)
                            if ENV_FILE_OR_VALUE is not None:
                                config[key] = ENV_FILE_OR_VALUE
                            else:
                                log_records.append(logging.LogRecord(level=logging.ERROR, msg=f" Environment variable {env_var} not found", args=(), exc_info=None, func=None, lineno=0, module=None))
        except Exception as e:
            log_records.append(logging.LogRecord(level=logging.ERROR, msg=f"Error loading {config_filename}: {str(e)}", args=(), exc_info=None, func=None, lineno=0, module=None))

    return config_dict, log_records
