def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_content: bin_content

    points = []
    for bin_index, bin_content in enumerate(hist):
        point_value = make_value(bin_content)

        if get_coordinate == "left":
            coordinate = bin_index
        elif get_coordinate == "right":
            coordinate = bin_index + 1
        elif get_coordinate == "middle":
            coordinate = (bin_index + bin_index + 1) / 2
        else:
            raise ValueError("Invalid get_coordinate value")

        points.append((coordinate,) + point_value)

    if scale is True and hasattr(hist, "scale"):
        for point in points:
            for i, value in enumerate(point[1:], start=1):
                point = point[:i] + (value / hist.scale,) + point[i+1:]

    return points
