            raise Invalid(f"{candidate} does not claim to provide {iface}")

    for name in iface.names():
        attr = getattr(candidate, name, None)
        if attr is None:
            raise Invalid(f"{candidate} does not define the attribute {name}")

        method = getattr(candidate.__class__, name, None)
        if method is None:
            raise Invalid(f"{candidate} does not define the method {name}")

        if not callable(method):
            raise Invalid(f"{candidate}.{name} is not callable")

        method_spec = method.__annotations__
        for arg, annotation in method_spec.items():
            if arg != 'return' and isinstance(annotation, type):
                arg_value = method.__get__(candidate, candidate.__class__).__dict__.get(arg)
                if not isinstance(arg_value, annotation):
                    raise Invalid(f"{candidate}.{name} argument {arg} is not an instance of {annotation}")

    return True
