def verifyObject(iface, candidate, tentative=False):
    from zope.interface import Invalid, implementedBy, implementer, provider

    if not tentative:
        if not iface.providedBy(candidate):
            raise Invalid(f"Candidate does not claim to provide {iface}")

    candidate_class = type(candidate)

    # Check methods
    expected_methods = iface.names()
    missing_methods = [
        method for method in expected_methods
        if not hasattr(candidate_class, method)
    ]
    if missing_methods:
        raise Invalid(f"Missing methods: {', '.join(missing_methods)}")

    # Check method signatures
    from zope.interface.common import interface
    interface.getInterface(candidate_class)
    for method_name, method in candidate_class.__dict__.items():
        if callable(method):
            expected = iface[method_name]
            actual = method
            try:
                interface.contains(expected, actual)
            except Invalid as e:
                raise Invalid(f"Incorrect signature for method {method_name}: {e}")

    # Check attributes
    expected_attributes = iface.names(True)
    missing_attributes = [
        attribute for attribute in expected_attributes
        if not hasattr(candidate_class, attribute)
    ]
    if missing_attributes:
        raise Invalid(f"Missing attributes: {', '.join(missing_attributes)}")

    return True

