def isoparse(self, dt_str):
    from datetime import datetime, timedelta
    from dateutil.tz import tzutc, tzoffset
    import re

    date_format_re = re.compile(r'(\d{4})(?:-(\d{2}))?(?:-(\d{2}))?')
    time_format_re = re.compile(r'(\d{2})(?::(\d{2}))?(?::(\d{2}))?(?:\.(\d+))?')
    tz_format_re = re.compile(r'([+-])(\d{2}):?(\d{2})')

    def parse_date(date_str):
        if not date_str:
            return None
        year, month, day = map(int, date_str.split("-"))
        return datetime(year, month, day)

    def parse_time(time_str):
        if not time_str:
            return None
        hours, minutes, seconds, subseconds = map(int, time_str.split(":"))
        subseconds /= 10**len(str(subseconds))
        return timedelta(hours=hours, minutes=minutes, seconds=seconds, microseconds=subseconds*1000)

    def parse_tz(tz_str):
        if not tz_str:
            return None
        sign, hours, minutes = map(int, tz_str.split(":"))
        hours *= (-1 if sign == '-' else 1)
        minutes *= (-1 if sign == '-' else 1)
        return tzoffset("UTC", hours * 3600 + minutes * 60)

    match = date_format_re.match(dt_str)
    if match:
        date_str, time_str, tz_str = match.group(1, 2, 3)
        date = parse_date(date_str)
        time = parse_time(time_str)
        tz = parse_tz(tz_str)
    else:
        date = None
        time = None
        tz = None

    dt = datetime.combine(date, time) if date and time else (date or time)
    return dt.replace(tzinfo=tz)

def _takes_ascii(func):
    def wrapper(self, dt_str):
        if not all(ord(c) < 128 for c in dt_str):
            raise ValueError("Input string must be in ASCII")
        return func(self, dt_str)
    return wrapper

