    from dateutil.tz import tzoffset, tzfile

    try:
        if isinstance(timestr, datetime.datetime):
            result = timestr.replace(**kwargs)
        else:
            result = _parse(timestr, **kwargs)

        if ignoretz:
            result = result.replace(tzinfo=None)

        if tzinfos:
            tzname = result.tzinfo.tzname(result)[0] if result.tzinfo else None
            if tzname and tzname in tzinfos:
                if isinstance(tzinfos[tzname], int):
                    result = result.replace(tzinfo=tzoffset(None, tzinfos[tzname]))
                elif isinstance(tzinfos[tzname], tzfile):
                    result = result.replace(tzinfo=tzinfos[tzname])
                elif callable(tzinfos[tzname]):
                    result = result.replace(tzinfo=tzinfos[tzname](tzname, result.utcoffset().total_seconds()))

        return result
    except Exception as e:
