class CustomTZInfo(tzinfo):
    def __init__(self, offset, name=None):
        self.offset = offset
        self.name = name or "Custom"

    def utcoffset(self, dt):
        return self.offset

    def tzname(self, dt):
        return self.name

    def dst(self, dt):
        return None

    def __repr__(self):
        return f"{self.__class__.__name__}({self.offset}, {self.name})"

def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    parse_result = parser.parse(timestr, **kwargs)
    if ignoretz:
        parse_result = parse_result.replace(tzinfo=None)
    elif tzinfos:
        for alias, tz in tzinfos.items():
            if hasattr(tz, 'utcoffset'):
                parse_result = parse_result.replace(tzinfo=tz)
                break
            elif isinstance(tz, int):
                parse_result = parse_result.replace(tzinfo=CustomTZInfo(tz, alias))
                break

    return parse_result
