from typing import Callable, Set, Tuple

def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set[str], str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    tag_chars = {"@", "*", "#"}
    in_code_block = False
    new_text = ""

    for i in range(len(text)):
        if text[i:i+3] == "```":
            in_code_block = not in_code_block
        if not in_code_block:
            if text[i] in tag_chars:
                # Find the end of the tag
                end = i + 1
                while end < len(text) and text[end] not in tag_chars.union({" "}) and text[end] not in ".,;!?":
                    end += 1
                tag = text[i:end]
                tags.add(tag)
                if replacer:
                    new_text += replacer(tag)
                else:
                    new_text += tag
                i = end - 1
            else:
                new_text += text[i]
        else:
            new_text += text[i]

    return tags, new_text

