            data['subject'] = subject.text
        for alias in root.findall('{http://pets.damnwidget.com/ns/xrd}Alias'):
            data['alias'] = alias.text
        for link in root.findall('{http://pets.damnwidget.com/ns/xrd}Link'):
            href = link.get('href')
            rel = link.get('rel')
            if href and rel:
                if 'links' not in data:
                    data['links'] = []
                data['links'].append({'href': href, 'rel': rel})
        return data
    except Exception as e:
        return {'error': str(e)}

