def list_of_file_names(settings_dirs, spec_option):
    """Generate a list of file names based on settings directories and a specification option.

    :param settings_dirs: A list of directories containing the settings files.
    :param spec_option: A string specifying the type of specification to use.
    :return: A list of file names that match the given settings directories and specification option.
    """
    import os

    file_names = []
    for settings_dir in settings_dirs:
        if os.path.exists(settings_dir):
            for root, _, files in os.walk(settings_dir):
                for file in files:
                    if spec_option in file:
                        file_names.append(os.path.join(root, file))
